practice.solution:
const readings: number[] = [12.1, 9.8, 15.3, 11.6, 13.9];

const min = Math.min(...readings);
const max = Math.max(...readings);
const average = readings.reduce((sum, r) => sum + r, 0) / readings.length;

console.log(`Min: ${min}`);
console.log(`Max: ${max}`);
console.log(`Average: ${average.toFixed(2)}`);

examples.code:
const scores: number[] = [88, 92, 79];

const first = scores[0];
//    ^? const first: number | undefined
if (first !== undefined) {
  console.log(`First: ${first.toFixed(1)}`);
  //                    ^? const first: number
}

const tenth = scores[9];
if (tenth === undefined) {
  console.log("There is no tenth score");
}

const names: string[] = ["Ana", "Ben", "Caro"];

const first = names[0] ?? "nobody";
//    ^? const first: string
const last = names.at(-1) ?? "nobody";
console.log(`First: ${first}, last: ${last}`);

const empty: string[] = [];
console.log(`Empty: ${empty[0] ?? "nobody"}, ${empty.at(-1) ?? "nobody"}`);

