//                             ^? (property) length: 2

function minMax(xs: number[]): [min: number, max: number] {
  return [Math.min(...xs), Math.max(...xs)];
}

const [low, high] = minMax([7, 2, 9, 4]);
console.log(`Low: ${low}, high: ${high}`);
console.log(`Range: ${high - low}`);

examples.explanation:
The return type promises exactly two numbers, so `low` and `high` are both `number` and `high - low` type-checks. Leave the return type off and TypeScript infers `number[]` for the returned array. Then each destructured value is `number | undefined`, and the subtraction no longer compiles:

```typescript error
function minMax(xs: number[]) {
  return [Math.min(...xs), Math.max(...xs)];
}

const [low, high] = minMax([7, 2, 9, 4]);
console.log(high - low);
```

