practice.solution:
export function splitBill(
  totalCents: number,
  people: number,
): [share: number, remainder: number] {
  return [Math.floor(totalCents / people), totalCents % people];
}

const [share, remainder] = splitBill(1000, 3);
console.log(`Each pays ${share} cents, ${remainder} cent left over`);
